+export function serialize(row: JobRow): Job {
+  return { id: row.id, status: row.status, input: row.input, steps: row.steps,
+    failAttempts: row.fail_attempts, attempts: row.attempts,
+    progress: { completed: row.completed, total: row.steps },
+    result: row.status === 'completed' ? { output: row.output ?? '' } : null,
+    error: row.status === 'failed' ? row.error : null,
+    createdAt: row.created_at, updatedAt: row.updated_at };
+}
+const rowFrom = (v: unknown): JobRow | undefined => v as JobRow | undefined;
+export function getJob(db: DatabaseSync, id: string): Job | undefined {
+  const row = rowFrom(db.prepare('SELECT * FROM jobs WHERE id=?').get(id));
+  return row && serialize(row);
+}
+export function listJobs(db: DatabaseSync): Job[] {
+  return (db.prepare('SELECT * FROM jobs ORDER BY seq DESC').all() as unknown as JobRow[]).map(serialize);
+}
+function transaction<T>(db: DatabaseSync, fn: () => T): T {
+  db.exec('BEGIN IMMEDIATE');
+  try { const value = fn(); db.exec('COMMIT'); return value; }
+  catch (e) { try { db.exec('ROLLBACK'); } catch {} throw e; }
+}
+export type CreateResult = { kind: 'created' | 'existing'; job: Job } | { kind: 'conflict' };
+export function createJob(db: DatabaseSync, payload: JobPayload, key?: string): CreateResult {
+  return transaction(db, () => {
+    if (key !== undefined) {
+      const found = rowFrom(db.prepare('SELECT * FROM jobs WHERE idempotency_key=?').get(key));
+      if (found) return found.input === payload.input && found.steps === payload.steps && found.fail_attempts === payload.failAttempts
+        ? { kind: 'existing', job: serialize(found) } : { kind: 'conflict' };
+    }
+    const now = new Date().toISOString();
+    const id = randomUUID();
+    db.prepare(`INSERT INTO jobs(id,input,steps,fail_attempts,status,attempts,completed,output,error,created_at,updated_at,idempotency_key,retry_at)
+      VALUES(?,?,?,?,'queued',0,0,NULL,NULL,?,?,?,0)`).run(id, payload.input, payload.steps, payload.failAttempts, now, now, key ?? null);
+    const row = rowFrom(db.prepare('SELECT * FROM jobs WHERE id=?').get(id))!;
+    return { kind: 'created', job: serialize(row) };
+  });
+}
+export function heartbeat(db: DatabaseSync): void {
+  db.prepare(`INSERT INTO worker_heartbeat(singleton,seen_at) VALUES(1,?) ON CONFLICT(singleton) DO UPDATE SET seen_at=excluded.seen_at`).run(Date.now());
+}
+export function workerIsUp(db: DatabaseSync): boolean {
+  const r = db.prepare('SELECT seen_at FROM worker_heartbeat WHERE singleton=1').get() as { seen_at: number } | undefined;
+  return !!r && Date.now() - r.seen_at <= 3000;
+}
+export function recoverRunning(db: DatabaseSync): JobRow | undefined {
+  return transaction(db, () => {
+    const row = rowFrom(db.prepare("SELECT * FROM jobs WHERE status='running' ORDER BY seq ASC LIMIT 1").get());
+    if (!row) return;
+    db.prepare("UPDATE jobs SET completed=0,updated_at=? WHERE id=?").run(new Date().toISOString(),row.id);
+    return rowFrom(db.prepare('SELECT * FROM jobs WHERE id=?').get(row.id));
+  });
+}
+export function claimJob(db: DatabaseSync): JobRow | undefined {
+  return transaction(db, () => {
+    const row = rowFrom(db.prepare("SELECT * FROM jobs WHERE status='queued' AND retry_at<=? ORDER BY seq ASC LIMIT 1").get(Date.now()));
+    if (!row) return;
+    const now = new Date().toISOString();
+    db.prepare("UPDATE jobs SET status='running',attempts=attempts+1,completed=0,output=NULL,error=NULL,updated_at=? WHERE id=?").run(now, row.id);
+    return rowFrom(db.prepare('SELECT * FROM jobs WHERE id=?').get(row.id));
+  });
+}
+export function setProgress(db: DatabaseSync, id: string, completed: number): void {
+  db.prepare("UPDATE jobs SET completed=?,updated_at=? WHERE id=? AND status='running'").run(completed, new Date().toISOString(), id);
+}
+export function retryOrFail(db: DatabaseSync, id: string, attempts: number): void {
+  const now = new Date().toISOString();
+  if (attempts >= 3) db.prepare("UPDATE jobs SET status='failed',completed=0,output=NULL,error='transient failure',updated_at=?,retry_at=0 WHERE id=?").run(now,id);
+  else db.prepare("UPDATE jobs SET status='queued',completed=0,output=NULL,error=NULL,updated_at=?,retry_at=? WHERE id=?").run(now,Date.now()+500,id);
+}
+export function completeJob(db: DatabaseSync, id: string, steps: number, output: string): void {
+  db.prepare("UPDATE jobs SET status='completed',completed=?,output=?,error=NULL,updated_at=?,retry_at=0 WHERE id=?").run(steps,output,new Date().toISOString(),id);
+}
